import{_ as e,o as t,c as s,a8 as i}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.05 状态管理思想","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.05-state-management.md","filePath":"comics/EP.05-state-management.md","lastUpdated":1793421673000}'),o={name:"comics/EP.05-state-management.md"};function l(r,a,n,d,h,c){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="ep-05-状态管理思想" tabindex="-1">EP.05 状态管理思想 <a class="header-anchor" href="#ep-05-状态管理思想" aria-label="Permalink to &quot;EP.05 状态管理思想&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../05-state-management">05-state-management.md</a>（props 钻井 / 单向数据流 / 服务端状态）· 示例：<code>examples/05-01-mini-redux.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君改个主题色，props 要穿七层——&quot;props 钻井&quot;之痛。</li><li><strong>第 2 格</strong>：码叔揭秘 Redux：dispatch → 纯 reducer → 新 state → 订阅更新，单向流动。</li><li><strong>第 3 格</strong>：像素酱实证 Zustand/Pinia 的选择器订阅：无关字段更新不再惊动整树。</li><li><strong>第 4 格</strong>：码叔结案——状态分家：服务端状态交给 TanStack Query，store 只放 UI 状态。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-props-钻井" tabindex="-1">第 1 格 · props 钻井 <a class="header-anchor" href="#第-1-格-·-props-钻井" aria-label="Permalink to &quot;第 1 格 · props 钻井&quot;">​</a></h3><ul><li>数据要跨多层传递，中间层既不使用也不关心，却必须透传；</li><li>改一个字段要动 N 个文件，层级越深成本越高；</li><li>本质问题：<strong>状态离使用者太远</strong>。</li></ul><h3 id="第-2-格-·-单向数据流-redux-思想" tabindex="-1">第 2 格 · 单向数据流（Redux 思想） <a class="header-anchor" href="#第-2-格-·-单向数据流-redux-思想" aria-label="Permalink to &quot;第 2 格 · 单向数据流（Redux 思想）&quot;">​</a></h3><ol><li>视图 <code>dispatch(action)</code> 描述&quot;发生了什么&quot;；</li><li>reducer 是<strong>纯函数</strong> <code>(state, action) =&gt; newState</code>，绝不原地修改；</li><li>store 保存新 state 并通知订阅者；</li><li>修改路径唯一 → 可预测、可回放、可时间旅行调试。</li></ol><h3 id="第-3-格-·-选择器订阅" tabindex="-1">第 3 格 · 选择器订阅 <a class="header-anchor" href="#第-3-格-·-选择器订阅" aria-label="Permalink to &quot;第 3 格 · 选择器订阅&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> s.user);</span></span></code></pre></div><ul><li>Zustand / Redux 的 <code>useSelector</code> 只比较选择器结果，结果不变不渲染；</li><li>Pinia 的 state 天然是响应式对象，字段级依赖自动追踪；</li><li>对比&quot;整棵 store 变了整树重渲染&quot;，切片订阅是性能分水岭。</li></ul><h3 id="第-4-格-·-状态分家" tabindex="-1">第 4 格 · 状态分家 <a class="header-anchor" href="#第-4-格-·-状态分家" aria-label="Permalink to &quot;第 4 格 · 状态分家&quot;">​</a></h3><ul><li><strong>服务端状态</strong>（接口数据）：交给 TanStack Query / SWR——缓存、失效、重取、去重开箱即用；</li><li><strong>跨页面 UI 状态</strong>（登录态、主题、购物车）：全局 store；</li><li><strong>局部状态</strong>（表单草稿、开关）：<code>useState</code> / <code>ref</code> 就地管理。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../05-state-management#_5-9-本章避坑清单">《5.9 本章避坑清单》</a></p></blockquote><ol><li>把服务端接口数据复制进全局 store，之后要手工维护&quot;何时重新拉取&quot;——失效逻辑必漏；</li><li>reducer 里做副作用（发请求、写 localStorage），破坏可预测性；</li><li>选择器每次返回新对象引用（如 <code>map</code>/<code>filter</code> 结果），导致订阅永远&quot;变了&quot;。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>Redux 单向数据流的完整链路？——<strong>dispatch → 纯 reducer 生成新 state → store 通知订阅者 → 视图更新</strong>。</li><li>选择器订阅解决什么问题？——<strong>只订阅用到的状态切片，无关更新不触发重渲染</strong>。</li><li>为什么服务端状态不该进全局 store？——<strong>它有自己的缓存/失效/重取生命周期，用 TanStack Query 管理更可靠，手工同步必漏</strong>。</li></ol>',19)])])}const g=e(o,[["render",l]]);export{p as __pageData,g as default};
